package co.edu.uco.seguridad.pdp.identity.application.usecase.impl;
import co.edu.uco.seguridad.pdp.commons.model.ResultPage; import co.edu.uco.seguridad.pdp.identity.application.primaryport.request.SearchUsersPageRequest; import co.edu.uco.seguridad.pdp.identity.application.primaryport.response.UserResponse; import co.edu.uco.seguridad.pdp.identity.application.secondaryport.repository.SecurityUserRepository; import co.edu.uco.seguridad.pdp.identity.application.usecase.SearchUsersPageUseCase; import reactor.core.publisher.Mono;
public final class SearchUsersPageUseCaseImpl implements SearchUsersPageUseCase {private final SecurityUserRepository users;public SearchUsersPageUseCaseImpl(SecurityUserRepository users){this.users=users;}public Mono<ResultPage<UserResponse>> execute(SearchUsersPageRequest i){return users.findPageByTenant(i.tenantId(),i.query(),i.window()).map(p->p.map(u->new UserResponse(u.id(),u.email().value(),u.name(),"",u.tenantId(),u.createdAt(),u.lastLoginAt())));}}
